%     along with this program.  If not, see <http://www.gnu.org/licenses/>.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

global EPtictoc EPmain

if nargin < 17
    OPT3 =1;
end

if nargin < 18
    SCALE =0;
end

if nargin < 19
    outfid =0;
end

if nargin < 20
    followupWithin =[];
end

if nargin < 21
    followupBetween =[];
end

if ~exist('epsilonType','var')
    epsilonType='GG';
end

if ~exist('theHeader','var')
    theHeader=cell(0);
end

if ~exist('allPostHoc','var')
    allPostHoc=0;
end

if ~exist('betweenLabels','var')
    betweenLabels=cell(0);
end

if ischar(outfid)
    msg{1}=[outfid ' is a string, not a file ID number.'];
    [msg]=ep_errorMsg(msg);
    return
end

for i=1:length(factorNames)
    if length(factorNames{i}) ~= 3
        msg{1}=['The factor name ' factorNames{i} ' is not three letters long.'];
        [msg]=ep_errorMsg(msg);
        return
    end
end

for i=1:length(factorGroupNames)
    if length(factorGroupNames{i}) ~= 3
        msg{1}=['The factor name ' factorGroupNames{i} ' is not three letters long.'];
        [msg]=ep_errorMsg(msg);
        return
    end
end

if isempty(elecFactors)
    elecFactors=zeros(length(factorNames));
end

if isempty(sessFactors)
    sessFactors=zeros(length(factorNames));
end

NX=ANOVAdata.subjects;
if isempty(NX)
    NX = size(Y,1);
end
if size(NX,1) > size(NX,2)
    NX=NX';
end

PER=ANOVAoptions.trimming;
NUMSIM=ANOVAoptions.bootstrap;
REPS=ANOVAoptions.reps;
SEED=ANOVAoptions.seed;
MISSING=ANOVAoptions.missing;
epsilonType=ANOVAoptions.epsilon;
posthocType=ANOVAoptions.posthoc;
betweenLabels=ANOVAinfo.betweenLvl;
covariate=ANOVAinfo.covariate;
GAVsubsTable=cell(2,2);

varNum = size(Y,2);
obsNum = size(Y,1);
grpNum = length(NX); %number of group cells
maxDigits = length(num2str(floor(max(max(Y)))))+2;

statsToolbox=0;
verList=ver;
if ~isempty(find(strcmp('Statistics and Machine Learning Toolbox',{verList.Name}), 1))
    statsToolbox=1;
end

if isempty(MISSING)
    MISSING=Inf;
    disp('MISSING set to Inf');
end

Y(Y==MISSING)=NaN; %the conventional code recognizes NaN but not missing data code number.

%calculate how many observations with missing data points
[NXnm, NXt, Ynm, Yt]=sampleSize(Y, NX, OPT1, PER, MISSING);
if ~isempty(find(NXnm==0, 1))
    if grpNum==1
        msg{1}='The data have zero members after dropping missing data points';
    else
        msg{1}='A group has zero members after dropping missing data points';
    end
    [msg]=ep_errorMsg(msg);
    return
end

if outfid == 0
    fileName=uiputfile('results.html','File name for output');
    if fileName == 0
        msg{1}='Something went wrong.';
        [msg]=ep_errorMsg(msg);
        return
    end
    fileName=[pwd filesep fileName];
    outfid=fopen(fileName,'w');
    internalFID = 1;
else
    internalFID = 0;
end

if outfid == -1
    msg{1}='Results output file not successfully created.';
    [msg]=ep_errorMsg(msg);
    return
end

ICCflag=0;

%determine which columns go with which withingroup levels

repFactor=1;
repCount=1;
lvlCount=1;
numFactors=length(levelNames);
factorTable=cell(numFactors,varNum);
for theFactor=numFactors:-1:1
    for iCol=1:varNum
        factorTable{theFactor,iCol}=levelNames{theFactor}(lvlCount);
        repCount=repCount+1;
        if repCount > repFactor
            repCount=1;
            lvlCount=lvlCount+1;
            if lvlCount > length(levelNames{theFactor})
                lvlCount=1;
            end
        end
    end
    repFactor=repFactor*length(levelNames{theFactor});
end

%determine which rows go with which betweengroup levels
repFactor=1;
repCount=1;
lvlCount=1;
numGroupFactors=length(levelGroupNames);
factorGroupTable=cell(grpNum,numGroupFactors);
for theFactor=numGroupFactors:-1:1
    if covariate(theFactor)~=2
        for row=1:grpNum
            factorGroupTable{row,theFactor}=levelGroupNames{theFactor}(lvlCount);
            repCount=repCount+1;
            if repCount > repFactor
                repCount=1;
                lvlCount=lvlCount+1;
                if lvlCount > length(levelGroupNames{theFactor})
                    lvlCount=1;
                end
            end
        end
        repFactor=repFactor*length(levelGroupNames{theFactor});
    end
end

%%%%%%compute within group contrasts%%%%%
facNum = length(factorNames);
if facNum==1 && isempty(deblank(factorNames{1}))
    facNum=0;
end
levelNum = zeros(facNum,1);

for iFac = 1:facNum
    levelNum(iFac)=length(levelNames{iFac});
end

if varNum ~= prod(levelNum)
    msg{1}=['Number of variables (' num2str(varNum) ') must equal product of within-group factor levels (' num2str(prod(levelNum)) ').'];
    [msg]=ep_errorMsg(msg);
    return
end

if length(factorNames)~= length(levelNames) && ~isempty(factorNames)
    msg{1}=['Number of within factors given names (' num2str(length(factorNames)) ') must equal number of within factors given level names (' num2str(length(levelNames)) ').'];
    [msg]=ep_errorMsg(msg);
    return
end

if sum(NX) ~= size(Y,1)
    msg{1}=['Number of observations (' num2str(size(Y,1)) ') must equal the sum of the between group sizes (' num2str(sum(NX)) ').'];
    [msg]=ep_errorMsg(msg);
    return
end

if length(factorGroupNames)~= length(levelGroupNames) && ~isempty(factorGroupNames)
    msg{1}=['Number of between factors given names (' num2str(length(factorGroupNames)) ') must equal number of between factors given level names (' num2str(length(levelGroupNames)) ').'];
    [msg]=ep_errorMsg(msg);
    return
end

contrast = [];
basicContrast = [];
facCombs = zeros(facNum,facNum);
contrast{1} = ones(1,varNum);
contrastName{1} = '';
contrastLevelNames{1} = ' ';
contrastFactors=zeros(1,facNum); %list of which factors are participating in a contrast

%get the means for each of the cells
% [MUHAT, STDIZER, RESULTS, MSE]=runRobust(Y, NX, ones(1,grpNum), contrast{1}', OPT1, PER, OPT2, 1, SEED, MISSING, OPT3, alpha, SCALE, LOC1, LOC2); %generate MUHAT
% if isempty(RESULTS)
%     return
% end

% cellMeans=zeros(grpNum,1,varNum); %trimmed means of the within cells (group variables, within effects, within levels)
% cellMeans(:,1,1)=mean(reshape(MUHAT',varNum,grpNum),1);
% cellVars=zeros(grpNum,1,varNum); %winsorized variance of the within cells (group variables, within effects, within levels)
% cellVars(:,1,1)=mean(reshape(diag(STDIZER)',varNum,grpNum),1);

theEffect=0;
for iInter=1:facNum %degree of interactions, from main effects on up
    comboList=nchoosek([1:facNum],iInter);
    for iEffect = 1:size(comboList,1) %which main effect/interaction
        theEffect=theEffect+1;
        theNames = [];
        contrastLevelNames{theEffect+1} = unique(cell2mat(factorTable(comboList(iEffect,:),:)'),'stable','rows'); %list of labels for the cell means output table
        contrastFactors(end+1,comboList(iEffect,:))=1;
        theContrast=1;
        contrastName{theEffect+1} = '';
        for iFactor=1:facNum %generate contrasts
            theFactor=find(iFactor==comboList(iEffect,:));
            if ~isempty(theFactor)
                if ~isempty(contrastName{theEffect+1})
                    contrastName{theEffect+1} = [contrastName{theEffect+1} ' * '];
                end
                contrastName{theEffect+1} = [contrastName{theEffect+1} factorNames{comboList(iEffect,theFactor)}];
                helmertContrast=zeros(levelNum(iFactor)-1,levelNum(iFactor));
                for iLevel=1:levelNum(iFactor)-1
                    helmertContrast(iLevel,iLevel)=levelNum(iFactor)-iLevel;
                    helmertContrast(iLevel,iLevel+1:end)=-1;
                end
                theContrast=kron(theContrast, helmertContrast);
            else
                theContrast=kron(theContrast, ones(1,levelNum(iFactor)));
            end
        end
        contrast{theEffect+1}=theContrast;
        % for iGroup = 1:grpNum %calculate the cell means and cell variances
        %     theMUHAT = MUHAT((iGroup-1)*varNum+1:iGroup*varNum,1);
        %     diagSTDIZER=diag(STDIZER);
        %     theSTDIZER = diagSTDIZER((iGroup-1)*varNum+1:iGroup*varNum,1);
        %     for iLevel=1:size(contrastLevelNames{theEffect+1},1)
        %         cellMeans(iGroup,theEffect+1,iLevel) = mean(theMUHAT(strcmp(contrastLevelNames{theEffect+1}(iLevel,:),cellstr(cell2mat(factorTable(comboList(iEffect,:),:)')))));
        %         cellVars(iGroup,theEffect+1,iLevel) = mean(theSTDIZER(strcmp(contrastLevelNames{theEffect+1}(iLevel,:),cellstr(cell2mat(factorTable(comboList(iEffect,:),:)')))));
        %     end
        % end
    end
end

%%%%%%compute between group contrasts%%%%%

facGroupNum = length(factorGroupNames); %number of group factors
groupContrast{1} = ones(1,grpNum);
contrastGroupName{1} = '';
betweenContrastFactors=zeros(1,facGroupNum); %list of which factors are participating in a contrast
contrastLevelGroupNames{1} = ' ';
% cellGroupMeans(1,1,:,:)=mean(cellMeans,1); %means of the group cells (group effects, group levels, within effects, within levels)
% cellGroupVars(1,1,:,:)=mean(cellVars,1); %variances of the group cells (group effects, group levels, within effects, within levels)

if facGroupNum >0
    levelGroupNum = zeros(facGroupNum,1);
    for iFac = 1:facGroupNum
        if covariate(iFac) == 2
            levelGroupNum(iFac)=1;
        else
            levelGroupNum(iFac)=length(levelGroupNames{iFac});
        end
    end

    %     if ~followup
    if grpNum ~= prod(levelGroupNum) %make sure factors are fully crossed
        msg{1}=['Number of groups (' num2str(grpNum) ') must equal product of between factor levels (' num2str(prod(levelGroupNum)) ').'];
        [msg]=ep_errorMsg(msg);
        return
    end
    %     end

    theEffect=0;
    for iInter=1:facGroupNum %degree of interactions, from main effects on up
        comboList=nchoosek([1:facGroupNum],iInter);
        for iEffect = 1:size(comboList,1) %which main effect/interaction
            theEffect=theEffect+1;
            theNames = [];
            if ~any(covariate(comboList(iEffect,:))==2)
                contrastLevelGroupNames{theEffect+1} = unique(cell2mat(factorGroupTable(:,comboList(iEffect,:))),'stable','rows'); %list of labels for the cell means output table
            else
                contrastLevelGroupNames{theEffect+1} = '';
            end
            betweenContrastFactors(end+1,comboList(iEffect,:))=1;
            theContrast=1;
            contrastGroupName{theEffect+1} = '';
            for iFactor=1:facGroupNum %generate contrasts
                theFactor=find(iFactor==comboList(iEffect,:));
                if ~isempty(theFactor)
                    if ~isempty(contrastGroupName{theEffect+1})
                        contrastGroupName{theEffect+1} = [contrastGroupName{theEffect+1} ' * '];
                    end
                    contrastGroupName{theEffect+1} = [contrastGroupName{theEffect+1} factorGroupNames{comboList(iEffect,theFactor)}];
                    helmertContrast=zeros(levelGroupNum(iFactor)-1,levelGroupNum(iFactor));
                    for iLevel=1:levelGroupNum(iFactor)-1
                        helmertContrast(iLevel,iLevel)=levelGroupNum(iFactor)-iLevel;
                        helmertContrast(iLevel,iLevel+1:end)=-1;
                    end
                    theContrast=kron(theContrast, helmertContrast);
                else
                    theContrast=kron(theContrast, ones(1,levelGroupNum(iFactor)));
                end
            end
            groupContrast{theEffect+1}=theContrast;
            % if ~any(covariate(comboList(iEffect,:))==2)
            %     for iLevel=1:size(contrastLevelGroupNames{theEffect+1},1) %calculate the group cell means
            %         cellGroupMeans(theEffect+1,iLevel,:,:) = mean(cellMeans(strcmp(contrastLevelGroupNames{theEffect+1}(iLevel,:),cellstr(cell2mat(factorGroupTable(:,comboList(iEffect,:))))),:,:),1);
            %         cellGroupVars(theEffect+1,iLevel,:,:) = mean(cellVars(strcmp(contrastLevelGroupNames{theEffect+1}(iLevel,:),cellstr(cell2mat(factorGroupTable(:,comboList(iEffect,:))))),:,:),1);
            %     end
            % else
            %     cellGroupMeans(theEffect+1,iLevel,:,:) = 0;
            %     cellGroupVars(theEffect+1,iLevel,:,:) = 0;
            % end
        end
    end
end

if ~followup
    if OPT2
        fprintf(outfid,'EP Toolkit version: %s</BR>\n',EPmain.preferences.EPver);
        fprintf(outfid,'Time Started: %s</BR>\n',char(datetime("now")));      
        fprintf(outfid,'Robust ANOVA based on SAS/IML code by Keselman, Wilcox, and Lix (2003),</BR>\n');
