    if sum(NX) ~= sum(NXnm)
        fprintf(outfid,['Number of subjects in each group after participants with missing data dropped from analysis: ' num2str(NXnm) '</BR>\n']);
    end
    if OPT1==1
        fprintf(outfid,['Number trimmed from extremes of each cell: ' num2str(floor(PER*sum(NXnm))) '</BR>\n']);
        if ~isscalar(NXnm)
            fprintf(outfid,['Number trimmed from extremes of each group cell: ' num2str(floor(PER*NXnm)) '</BR>\n']);
        end
    end
    fprintf(outfid,['Uncorrected alpha criteria: ' num2str(alpha.uncorrected) '</BR>\n']);
    fprintf(outfid,['Familywise (e.g., a set of PCA factors) corrected alpha criteria: ' num2str(alpha.corrected) '</BR>\n']);
    fprintf(outfid,['Post-hocs use the Dunn-Šidák MCP correction.  </BR>\n']);
    if ~OPT2 && statsToolbox
        fprintf(outfid,['Pairwise between-group post-hoc MCP correction using ' posthocType '.</BR>\n']);
    end
    fprintf(outfid,['Per commonly accepted practice, post-hoc MCP correction not applied to simple main effects and interactions.  </BR>\n']);
    if ~isempty(theHeader)
        fprintf(outfid,['Familywise (e.g., a set of PCA factors) Dunn-Šidák MCP correction factor: ' num2str(theHeader{end}) '</BR>\n']);

        fprintf(outfid,[repmat('#',1,60) '</BR>\n']);
        fprintf(outfid,['ANOVA Header Information</BR>\n']);
        fprintf(outfid,[repmat('#',1,60) '</BR>\n']);
        for iHeader=1:length(theHeader)-3
            fprintf(outfid,[theHeader{iHeader} '</BR>\n']);
        end
        if isempty(strfind(theHeader{iHeader+1},char(9)))
            delimit=',';
        else
            delimit=char(9);
        end
        spaceIndex=strfind([delimit theHeader{iHeader+1} delimit],delimit);
        fprintf(outfid,[theHeader{iHeader+1}(spaceIndex(ANOVAinfo.leftColumn):(spaceIndex(ANOVAinfo.rightColumn+1)-2)) '</BR>\n']);
        spaceIndex=strfind([delimit theHeader{iHeader+2} delimit],delimit);
        fprintf(outfid,[theHeader{iHeader+2}(spaceIndex(ANOVAinfo.leftColumn):(spaceIndex(ANOVAinfo.rightColumn+1)-2)) '</BR>\n']);
    end
end

%generate corrected dataset for vector scaling test in case it is needed

%later in the code, should make the assumption that the electrode factors are the lowest and session factors are the highest.
totElecLevels=1;
for i=1:length(levelNum)
    if elecFactors(i)
        totElecLevels=totElecLevels*levelNum(i);
    end
end
totSessLevels=1;
for i=1:length(levelNum)
    if sessFactors(i)
        totSessLevels=totSessLevels*levelNum(i);
    end
end

%if this is a follow-up analysis rather than the primary analysis
if ~isempty(followupBetween) || ~isempty(followupWithin)
    theContrast=zeros(length(followupBetween),length(contrastGroupName));
    for theFactor = 1:length(followupBetween)
        theMatches=regexp(contrastGroupName,['^' followupBetween{theFactor} '\s\w*']);
        theMatches2=regexp(contrastGroupName,['\w*\s' followupBetween{theFactor} '\s\w*']);
        theMatches3=regexp(contrastGroupName,['^' followupBetween{theFactor} '\w*']);
        theMatches4=regexp(contrastGroupName,['\w*\s' followupBetween{theFactor} '$']);
        for i=1:length(contrastGroupName)
            theContrast(theFactor,i)= ~isempty(theMatches{i}) || ~isempty(theMatches2{i}) || ~isempty(theMatches3{i}) || ~isempty(theMatches4{i});
        end
    end
    betweenContrastList=find(sum(theContrast,1) == length(followupBetween), 1 ); %the lowest level contrast that contains all the factor names desired
else
    betweenContrastList=1:size(groupContrast,2);
end

%scale contrast weights so that the positive and negative terms sum to +1
%and -1 respectively since this affects the ES and the CI statistics
%although not the overall test statistic.
%assume sum of positive and negative weights equal each other
%except for case where all weights are positive.

% for iContrast=1:length(groupContrast)
%     posWeights=find(sign(groupContrast{iContrast})==1);
%     scaleWeights=sum(groupContrast{iContrast}(posWeights));
%     groupContrast{iContrast}=groupContrast{iContrast}/scaleWeights;
% end
% for iContrast=1:length(contrast)
%     posWeights=find(sign(contrast{iContrast})==1);
%     scaleWeights=sum(contrast{iContrast}(posWeights));
%     contrast{iContrast}=contrast{iContrast}/scaleWeights;
% end

if ~OPT2 && statsToolbox
    %set up ANOVA tables for all the simple effects in advance for conventional ANOVAs
    [mainAnovaTable, mainRM] = setupANOVA(Y, factorTable, factorGroupTable, facNum, facGroupNum, varNum, contrastName, contrastGroupName, factorNames, factorGroupNames, betweenLabels);
end

%the between main effect or interaction contrast
for betweenGroup = betweenContrastList
    %     if ~((length(factorGroupNames)==1) && strcmp(factorGroupNames{1},'   ')) && ~((betweenGroup==1) && ((length(factorNames)==1) && strcmp(factorNames{1},'   ')))
    %         fprintf(outfid,[repmat('&nbsp;',1,followup*2) '</BR>\n' repmat('#',1,60) '</BR>\n']);
    %         fprintf(outfid,[repmat('&nbsp;',1,followup*2) contrastGroupName(betweenGroup,:) '</BR>\n']);
    %     end

    if ~isempty(followupBetween) || ~isempty(followupWithin)
        theContrast=zeros(length(followupWithin),length(contrastName));
        for theFactor = 1:length(followupWithin)
            theMatches=regexp(contrastName,['^' followupWithin{theFactor} '\s\w*']);
            theMatches2=regexp(contrastName,['\w*\s' followupWithin{theFactor} '\s\w*']);
            theMatches3=regexp(contrastName,['^' followupWithin{theFactor} '\w*']);
            theMatches4=regexp(contrastName,['\w*\s' followupWithin{theFactor} '$']);
            for i=1:length(contrastName)
                theContrast(theFactor,i)= ~isempty(theMatches{i}) || ~isempty(theMatches2{i}) || ~isempty(theMatches3{i}) || ~isempty(theMatches4{i});
            end
        end
        withinContrastList=find(sum(theContrast,1) == length(followupWithin), 1 ); %the lowest level contrast that contains all the factor names desired
    else
        if betweenGroup == 1
            firstWithin = 2; %analysis dropping both between and within factors would be meaningless
        else
            firstWithin = 1;
        end
        withinContrastList=firstWithin:size(contrast,2);
    end

    for withinGroup = withinContrastList
        ep_tictoc;if EPtictoc.stop;return;end
        if (length(contrast{withinGroup}) > 1) || ((betweenGroup > 1) && (withinGroup == 1))
            %             if ~((length(factorNames)==1) && strcmp(factorNames{1},'   '))
            %                 fprintf(outfid,[repmat('&nbsp;',1,followup*2) '</BR>\n' repmat('-',1,60) '</BR>\n']);
            %                 fprintf(outfid,[repmat('&nbsp;',1,followup*2) contrastName(withinGroup,:) '</BR>\n']);
            %             end
            fprintf(outfid,[repmat('&nbsp;',1,followup*2) '</BR>\n' repmat('-',1,60) '</BR>\n']);

            betweenName=contrastGroupName{betweenGroup};
            withinName=contrastName{withinGroup};
            if ~isempty(betweenName) && ~isempty(withinName)
                withinName=['* ' withinName];
            end
            fprintf(outfid,[repmat('&nbsp;',1,followup*2) '<em>' betweenName '</em> ' withinName '</BR>\n']);

            %generate collapsed cells of the present contrast
            withinLevelList=cell2mat(factorTable(find(contrastFactors(withinGroup,:)),:))';
            withinUniqueList=unique(withinLevelList,'stable','rows');
            withinLevelNum=max(1,size(withinUniqueList,1));

            betweenLevelList=cell2mat(factorGroupTable(:,find(betweenContrastFactors(betweenGroup,:))));
            betweenUniqueList=unique(betweenLevelList,'stable','rows');
            betweenLevelNum=max(1,size(betweenUniqueList,1));

            cY=zeros(size(Ynm,1),withinLevelNum);
            cNX=zeros(1,betweenLevelNum);
            ctrimmedNX=zeros(betweenLevelNum,1);
            cBcontrast=zeros(size(groupContrast{betweenGroup},1),betweenLevelNum);
            cWcontrast=zeros(size(contrast{withinGroup},1),withinLevelNum);
            cNXstart=0;
            for iCb=1:betweenLevelNum
                if isempty(betweenUniqueList)
                    cBlist=[1:length(NXnm)];
                else
                    cBlist=find(all(betweenUniqueList(iCb,:)==betweenLevelList,2));
                end
                cNX(iCb)=sum(NXnm(cBlist));
                ctrimmedNX(iCb)=sum(NXt(cBlist));
                cBcontrast(:,iCb)=groupContrast{betweenGroup}(:,cBlist(1));
                for iCbList=1:length(cBlist)
                    if cBlist(iCbList)==1
                        Ystart=0;
                    else
                        Ystart=sum(NXnm(1:cBlist(iCbList)-1));
                    end
                    for iCw=1:withinLevelNum
                        if isempty(withinUniqueList)
                            cWlist=1;
                        else
                            cWlist=find(all(withinUniqueList(iCw,:)==withinLevelList,2));
                        end
                        if iCbList==1
                            cWcontrast(:,iCw)=contrast{withinGroup}(:,cWlist(1));
                        end
                        cY(1+cNXstart:cNXstart+NXnm(cBlist(iCbList)),iCw)=mean(Ynm(1+Ystart:sum(NXnm(1:cBlist(iCbList))),cWlist),2);
                    end
                    cNXstart=cNXstart+NXnm(cBlist(iCbList));
                end
            end
            cY=cY(1:sum(cNX),:);

            %generate GAVsubs table
            if isempty(followupBetween) && isempty(followupWithin)
                cStart=1;
                for iGroupLevel=1:length(contrastLevelGroupNames{betweenGroup})
                    if betweenGroup==1
                        groupLevelName='all';
                    else
                        groupLevelName=contrastLevelGroupNames{betweenGroup}(iGroupLevel,:);
                    end
                    theGroupLevel=find(strcmp(groupLevelName,GAVsubsTable(:,1)),1);
                    if isempty(theGroupLevel)
                        GAVsubsTable{end+1,1}=groupLevelName;
                        GAVsubsTable{end,2}=ANOVAdata.index(cStart:sum(cNX(1:iGroupLevel)));
                        theGroupLevel=size(GAVsubsTable,1);
                    end
                    for iLevel=1:length(contrastLevelNames{withinGroup})
                        if withinGroup==1
                            levelName='all';
                        else
                            levelName=contrastLevelNames{withinGroup}(iLevel,:);
                        end
                        theLevel=find(strcmp(levelName,GAVsubsTable(1,:)),1);
                        if isempty(theLevel)
                            GAVsubsTable{1,end+1}=levelName;
                            theLevel=size(GAVsubsTable,2);
                            if strcmp(levelName,'all')
                                GAVsubsTable{2,theLevel}=[1:varNum]';
                            else
                                GAVsubsTable{2,theLevel}=find(strcmp(levelName,cellstr(withinLevelList)));
                            end
                            GAVsubsTable{2,theLevel}=[GAVsubsTable{2,theLevel},ones(size(GAVsubsTable{2,theLevel}))];
                        end
                        %rows with missing numbers already dropped (Ynm)
                        trimNum=(floor(PER.*cNX(iGroupLevel)));
                        [cellY, cellOrder]=sort(cY(cStart:sum(cNX(1:iGroupLevel)),iLevel));
                        cellTrimOrder=cellOrder(1+trimNum:end-trimNum);
                        GAVsubsTable{theGroupLevel,theLevel}=ANOVAdata.index(cStart:sum(cNX(1:iGroupLevel)));
                        GAVsubsTable{theGroupLevel,theLevel}=GAVsubsTable{theGroupLevel,theLevel}(cellTrimOrder);
                    end
                    cStart=cStart+cNX(iGroupLevel);
                end
            end

            [cMUHAT, cSTDIZER, ~, cMSE]=runRobust(cY, cNX, cBcontrast, cWcontrast', OPT1, PER, OPT2, 1, SEED, MISSING, 0, alpha, SCALE, LOC1, LOC2);
            if isempty(cMUHAT)
                msg='Error: ANOVA run aborted.';
                [msg]=ep_errorMsg(msg);
                return
            end

            testResults=[];
            if OPT2
                %robust statistics
                resultsTot=cell(REPS,1);
                pList=zeros(REPS,1);
                if ft_hastoolbox('DISTCOMP') && (EPmain.preferences.advanced.parallel==1)
                    ep_tictoc;if EPtictoc.stop;return;end
                    parfor iRep=1:REPS
                        [~, ~, RESULTS, ~]=runRobust(cY, cNX, cBcontrast, cWcontrast', OPT1, PER, OPT2, NUMSIM, SEED*iRep, MISSING, 0, alpha, SCALE, LOC1, LOC2);
                        resultsTot{iRep}=RESULTS;
                        pList(iRep)=RESULTS(4);
                    end
                else
                    for iRep=1:REPS
                        ep_tictoc;if EPtictoc.stop;return;end
                        [~, ~, RESULTS, ~]=runRobust(cY, cNX, cBcontrast, cWcontrast', OPT1, PER, OPT2, NUMSIM, SEED*iRep, MISSING, 0, alpha, SCALE, LOC1, LOC2);
                        resultsTot{iRep}=RESULTS;
                        pList(iRep)=RESULTS(4);
                    end
                end
                [A B]=sort(pList);
                RESULTS=resultsTot{find(B==ceil(length(pList)/2))};
                if isempty(RESULTS)
                    return
                end
                [NXnm, NXt, Ynm, Yt]=sampleSize(Y, NX, OPT1, PER, MISSING);
                alpha.pvar=std(pList)*2;
                testResults.statsType='robust';
                testResults.GPOWERtest='';
                if (withinLevelNum==1) && (betweenLevelNum==2)
                    testResults.effectSizeTest='d<sub>R</sub>'; %robust d Algina,Keselman,Penfield (2005a)
                elseif (withinLevelNum==2) && (betweenLevelNum==1)
                    testResults.effectSizeTest='d<sub>R</sub>'; %robust d Algina,Keselman,Penfield (2005b)
                elseif  (withinLevelNum>1) && (betweenLevelNum==1)
                    testResults.effectSizeTest='D'; %projection distance Wilcox (2022)
                elseif (withinLevelNum==1) && (betweenLevelNum>1)
                    testResults.effectSizeTest=char(hex2dec('03be')); %xi, for explanatory measure of effect (Wilcox & Tian, 2011)
                else
                    testResults.effectSizeTest='';
                end
                testResults.stat=RESULTS(1);
                testResults.numDF=RESULTS(2);
                testResults.denDF=RESULTS(3);
                testResults.pValue=RESULTS(4);
                testResults.epsilon=NaN;
                testResults.MSE=cMSE;
                testResults.statsTest='N-way';
                testResults.GPOWER=NaN;
                if withinLevelNum > 1
                    Rmatrix=pinv(diag(sqrt(diag(cSTDIZER))))*cSTDIZER*pinv(diag(sqrt(diag(cSTDIZER))));
                    testResults.meanR=mean(Rmatrix(find(~tril(ones(size(Rmatrix))))));
                else
                    testResults.meanR=[];
                end

                %effect size as only the matlab code computes effect sizes.
                ep_tictoc;if EPtictoc.stop;return;end
                [~, ~, esRESULTS, ~]=ep_WJGLMml_mat(cY, cNX, cBcontrast, cWcontrast', OPT1, PER, OPT2, NUMSIM, SEED, MISSING, OPT3, alpha, SCALE, LOC1, LOC2);
                testResults.effectSize=esRESULTS(5);
                testResults.lowerConfid=esRESULTS(6);
                testResults.upperConfid=esRESULTS(7);
            else
                %conventional statistics
                if statsToolbox
                    testResults = runANOVA(mainAnovaTable, mainRM, factorGroupTable, factorTable, betweenGroup, withinGroup, contrastGroupName, contrastName, contrast, epsilonType);
                else
                    %handrolled conventional ANOVAs
                    disp('Not functional yet');
                    return
                    %                     [MUHAT, STDIZER, RESULTS, MSE]=ep_WJGLMml_mat(Y, NX, groupContrast{betweenGroup}, contrast{withinGroup}', OPT1, PER, OPT2, NUMSIM, SEED, MISSING, OPT3, alpha, SCALE, LOC1, LOC2);
                end
                alpha.pvar=0;
            end

            ep_tictoc;if EPtictoc.stop;return;end
            errorFlag=ep_printADFResults(testResults, alpha, followup, outfid, ANOVAoptions);
            if errorFlag
                msg='Error: ANOVA run aborted.';
                [msg]=ep_errorMsg(msg);
                return
            end

            format long

            if withinLevelNum || betweenLevelNum
                %only if no covariates
                %print out the cell means
                tableCounter=tableCounter+1;
                if OPT1
                    fprintf(outfid,[repmat('&nbsp;',1,followup*2) '<p id=label' num2str(tableCounter) '>Averaged Trimmed Cell Means (Winsorized Standard Deviations):&nbsp;</p>\n']);
                else
                    fprintf(outfid,[repmat('&nbsp;',1,followup*2) '<p id=label' num2str(tableCounter) '>Averaged Cell Means (Standard Deviations):&nbsp;</p>\n']);
                end
                theCellNames = contrastLevelNames{withinGroup};
                line = '&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;';
                for theCell = 1:size(theCellNames,1)
                    theName = theCellNames(theCell,:);
                    line = [line theName repmat('&nbsp;',1,maxDigits+3-length(theName))];
                end
                theLine = [repmat('&nbsp;',1,followup*2) line]; %the line with the level labels
                fprintf(outfid,['<p id=plot' num2str(tableCounter) '>' theLine '</p>\n']);

                theBetweenNames = contrastLevelGroupNames{betweenGroup};
                LCImatrix=zeros(withinLevelNum,betweenLevelNum);
                UCImatrix=zeros(withinLevelNum,betweenLevelNum);
                for iBetween = 1:betweenLevelNum
                    theData = [theBetweenNames(iBetween,:) repmat('&nbsp;',1,5-length(theBetweenNames(iBetween,:)))]; %the between group level name
                    theData = strrep(theData,' ','&nbsp;');
                    if followup
                        theData=['<font size=''1''>' theData];
                    else
                        theData=['<font size=''2''>' theData];
                    end
                    for forWithin = 1:withinLevelNum
                        eval(['theNumber = sprintf(''%+' num2str(maxDigits) '.2f'', cMUHAT(forWithin+withinLevelNum*(iBetween-1)));']);
                        theData = [theData theNumber];
                        theData = [theData repmat('&nbsp;',1,maxDigits-length(theNumber)+3)];
                    end

                    theDataSD=theData;
                    theDataSE=theData;
                    theDataN=theData;
                    theDataCI=theData;
                    sampleN=cNX(iBetween);
                    trimmedSampleN=ctrimmedNX(iBetween);
                    for forWithin = 1:withinLevelNum
                        theSD=sqrt(cSTDIZER(forWithin+withinLevelNum*(iBetween-1),forWithin+withinLevelNum*(iBetween-1)));
                        theSE=((sampleN-1)/(trimmedSampleN-1))*theSD/sqrt(sampleN);
                        %compute Cousineau-Morey standard errors for within-factors
                        if withinLevelNum > 1
                            %the MSE is first computed as the interaction term with subjects and only then Winsorized, so here too first normalized and then winsorized STD
                            cmY=cY(1+sum(cNX(1:iBetween-1)):sum(cNX(1:iBetween)),forWithin)-mean(cY(1+sum(cNX(1:iBetween-1)):sum(cNX(1:iBetween)),:),2); %Cousineau scaling
                            [cmMUHAT, cmSTDIZER, cmRESULTS, ~]=ep_WJGLMml_mat(cmY, sampleN, 1, 1, OPT1, PER, OPT2, 499, SEED, MISSING, OPT3, alpha, SCALE, LOC1, LOC2);
                            cmSD=sqrt(cmSTDIZER);
                            cmSE=((sampleN-1)/(trimmedSampleN-1))*cmSD/sqrt(sampleN);
                            %Morey correction
                            theMorey=1;
                            for iFactor=1:size(theCellNames,2)
                                factorLevelNum=length(unique(theCellNames(:,iFactor)));
                                theMorey=theMorey*factorLevelNum/(factorLevelNum-1);
                            end
                            cmSE=cmSE*theMorey;
                        else
                            cmSE=theSE;
                            [cmMUHAT, cmSTDIZER, cmRESULTS, ~]=ep_WJGLMml_mat(cY, sampleN, 1, 1, OPT1, PER, OPT2, 499, SEED, MISSING, OPT3, alpha, SCALE, LOC1, LOC2);
                        end

                        %standard deviation
                        if any(abs(cY)>1,'all')
                            eval(['theNumber = sprintf(''%+' num2str(maxDigits) '.2f'', theSD);']);
                        else
                            eval(['theNumber = sprintf(''%+' num2str(maxDigits) '.4f'', theSD);']);
                        end
                        theDataSD = [theDataSD ' (' theNumber  ')'];

                        %Cousineau-Morey standard error.  Robust SE: Wilcox (2022) p. 65.
                        if any(abs(cY)>1,'all')
                            eval(['theNumber = sprintf(''%+' num2str(maxDigits) '.2f'', cmSE);']);
                        else
                            eval(['theNumber = sprintf(''%+' num2str(maxDigits) '.4f'', cmSE);']);
                        end
                        theDataSE = [theDataSE ' (' theNumber  ')'];

                        %sample size
                        theNumber = num2str(trimmedSampleN);
                        theDataN = [theDataN ' (' theNumber  ')'];

                        %confidence interval for individual cells
                        stdz=mean(sqrt(diag(cmSTDIZER)));
                        theLCI=cmRESULTS(6)*stdz; %dR effect size times standardizer results in cell mean effect
                        theUCI=cmRESULTS(7)*stdz;
                        if any(abs(cY)>1,'all')
                            eval(['theNumber = sprintf(''%+' num2str(maxDigits) '.2f to %+' num2str(maxDigits) '.2f'',cMUHAT(forWithin)+theLCI,cMUHAT(forWithin)+theUCI);']);
                        else
                            eval(['theNumber = sprintf(''%+' num2str(maxDigits) '.4f to %+' num2str(maxDigits) '.4f'',cMUHAT(forWithin)+theLCI,cMUHAT(forWithin)+theUCI);']);
                        end
                        theDataCI = [theDataCI ' (' theNumber  ')'];

                        LCImatrix(forWithin,iBetween)=theLCI; %for plotting the error bar figures
                        UCImatrix(forWithin,iBetween)=theUCI; %for plotting the error bar figures
                    end
                    cellTables{end+1,1}=theDataSD;
                    cellTables{end,2}=theDataSE;
                    cellTables{end,3}=theDataN;
                    cellTables{end,4}=theDataCI;
                    cellTables{end,5}='';
                    fprintf(outfid,['<p id=stats' num2str(size(cellTables,1)) '>' repmat('&nbsp;',1,followup*2) theDataSD '</p>\n']); %the cell means and standard deviations
                end

                %error bar plots
                hPlot = figure('doublebuffer','off','Visible','Off','WindowStyle', 'Docked');
                hBar=bar([1:withinLevelNum],reshape(cMUHAT,withinLevelNum,[]));

                hold on

                % Calculate the number of bars in each group https://stackoverflow.com/questions/65734026/how-to-plot-errorbars-in-a-grouped-bar
                nbars = betweenLevelNum;
                % Get the x coordinate of the bars
                x = [];
                for i = 1:nbars
                    x = [x ; hBar(i).XEndPoints];
                end
                % Plot the errorbars
                plotCells = errorbar(x',reshape(cMUHAT,withinLevelNum,[]),LCImatrix,UCImatrix,'k','linestyle','none');
                % for iBetween = 1:betweenLevelNum
                %     plotCells(iBetween).Color = [0 0 0];
                %     plotCells(iBetween).LineStyle = 'none';
                % end
                if betweenLevelNum > 1
                    legend(theBetweenNames);
                end
                % xlabel('Within Cells');
                xticklabels(theCellNames)

                maxM=max(cMUHAT,[],'all');
                minM=min(cMUHAT,[],'all');
                if (sign(maxM)==sign(minM)) && xor((abs(maxM) >= 1),(abs(minM) >= 1))
                    minMstr=num2str(minM);
                    maxMstr=num2str(maxM);
                    minLength=min(length(minMstr),length(maxMstr));
                    diffDigit=min(find(double(minMstr(1:minLength))-double(maxMstr(1:minLength))));
                    if isempty(diffDigit)
                        diffDigit=1;
                    else
                        if abs(maxM) < 1
                            diffDigit=diffDigit-2; %don't include either the leading 0 or the decimal point
                        end
                    end
                else
                    diffDigit=1;
                end
                if abs(maxM) >= 1
                    nIntegers = numel(extractBefore(num2str(abs(maxM)), '.'));
                    if nIntegers ==0
                        nIntegers = length(num2str(maxM));
                    end
                    maxY=ceil(maxM/10.^(nIntegers-2+diffDigit))*10.^(nIntegers-2+diffDigit);
                else
                    P=num2str(abs(maxM));
                    Pp=findstr('.',P);
                    Pz=findstr(P(Pp+1:length(P)),'0'); %list of zeros after the decimal
                    if isempty(Pz) || Pz(1)>1
                        iSigDigits=1;
                    else
                        iSigDigits=Pz(1);
                    end
                    maxY=ceil(maxM*10.^(iSigDigits+diffDigit))/10.^(iSigDigits+diffDigit);
                end

                if abs(minM) >= 1
                    nIntegers = numel(extractBefore(num2str(abs(minM)), '.'));
                    if nIntegers ==0
                        nIntegers = length(num2str(minM));
                    end
                    minY=floor(minM/10.^(nIntegers-2+diffDigit))*10.^(nIntegers-2+diffDigit);
                else
                    P=num2str(abs(minM));
                    Pp=findstr('.',P);
                    Pz=findstr(P(Pp+1:length(P)),'0'); %list of zeros after the decimal
                    if isempty(Pz) || Pz(1)>1
                        iSigDigits=1;
                    else
                        iSigDigits=Pz(1);
                    end
                    minY=floor(minM*10.^(iSigDigits+diffDigit))/10.^(iSigDigits+diffDigit);
                end

                ylim([minY maxY]);

                hold off

                saveas(hPlot,'EPtempFigure.png');
                fid = fopen('EPtempFigure.png');
                V = fread(fid,'*uint8');
                fclose(fid);
                base64plot = matlab.net.base64encode(V);
                % frm=getframe(hPlot); %https://www.mathworks.com/matlabcentral/answers/505798-save-the-output-figure-as-binary-image
                % img=frame2im(frm);
                % base64plot=base64encode(img);
                plotTables{end+1,1}=base64plot;
                plotTables{end,2}=theLine;

                %outlier plots
                %based on code from https://stackoverflow.com/questions/53106076/multiple-vertical-histograms-plot-in-matlab

                hPlot = figure('doublebuffer','off','Visible','Off','WindowStyle', 'Docked');
                [cNXnm, cNXt, cYnm, cYt]=sampleSize(cY, cNX, OPT1, PER, MISSING);
                numBins=20;
                hold on
                for iBcell=1:betweenLevelNum
                    for iWcell=1:withinLevelNum
                        [N,edges] = histcounts(cY(1+sum(cNX(1:iBcell-1)):sum(cNX(1:iBcell)),iWcell),numBins);
                        [trimN,~] = histcounts(cYt(1+sum(cNXt(1:iBcell-1)):sum(cNXt(1:iBcell)),iWcell),edges);
                        subplot(betweenLevelNum,withinLevelNum,(iBcell-1)*withinLevelNum+iWcell);
                        hold on
                        barh(N,'red');
                        barh(trimN,'blue');
                        xticks([]);
                        yticks(2:2:numBins)
                        yticklabels(edges(2:2:numBins));
                        xlabel(theCellNames(iWcell,:));
                        if iWcell==1
                            ylabel(theBetweenNames(iBcell,:));
                        end
                        box off;          % Remove box on right side of plot
                    end
                end
                hold off

                saveas(hPlot,'EPtempFigure.png');
                fid = fopen('EPtempFigure.png');
                V = fread(fid,'*uint8');
                fclose(fid);
                base64plot = matlab.net.base64encode(V);
                plotTables{end,3}=base64plot;
            end

            %perform vector scaling test.  The resulting cell means are not reported because, as demonstrated by Haig,
            %Gordon, & Hook (1997), they are not meaningful in of themselves.
            if testResults.pValue <= alpha.uncorrected && ~isempty(elecFactors) && ~isempty(contrastFactors)
                if any(and(contrastFactors(withinGroup,:),elecFactors')) && any((contrastFactors(withinGroup,:)-elecFactors')>0) %both electrode & non-electrode factors?
                    testResultsMW=[];

                    %scaling is done within each cell (defined by within factors other than electrode factors and between factors) with only electrode levels within each such
                    %cell.  The scaling is based on the mean value for each cell per McCarthy & Wood (1985) to get "a more stable
                    %estimate."  The mean values are the trimmed means in order to keep the scaling procedure consistent with the
                    %robust statistic.  The statement made in Dien & Santuzzi (2005) that Haig, Gordon, & Hook (1997) argued for calculating
                    %the vector scores based on the individual subjects was an error.
                    %if the data is from spatial PCA, should ignore as there is no variance to test between channels.

                    Yscaled=zeros(size(cY));
                    for iCol=1:totElecLevels:size(cY,2)
                        for iGroup=1:length(cNX)
                            Yscaled(1+sum(cNX(1:iGroup-1)):sum(cNX(1:iGroup)),iCol:iCol+totElecLevels-1)=cY(1+sum(cNX(1:iGroup-1)):sum(cNX(1:iGroup)),iCol:iCol+totElecLevels-1)/sqrt(sum(cMUHAT((iGroup-1)*varNum+iCol:(iGroup-1)*varNum+iCol+totElecLevels-1).^2));
                        end
                    end

                    if OPT2
                        %robust statistics
                        resultsTot=cell(REPS,1);
                        pList=zeros(REPS,1);
                        if ft_hastoolbox('DISTCOMP') && (EPmain.preferences.advanced.parallel==1)
                            ep_tictoc;if EPtictoc.stop;return;end
                            parfor iRep=1:REPS
                                [~, ~, RESULTSMW, ~]=runRobust(Yscaled, cNX, cBcontrast, cWcontrast', OPT1, PER, OPT2, NUMSIM, SEED*iRep, MISSING, 0, alpha, SCALE, LOC1, LOC2);
                                resultsTot{iRep}=RESULTSMW;
                                pList(iRep)=RESULTSMW(4);
                            end
                            [~, ~, RESULTSMW, MSE]=runRobust(Yscaled, cNX, cBcontrast, cWcontrast', OPT1, PER, OPT2, NUMSIM, 1, MISSING, OPT3, alpha, SCALE, LOC1, LOC2);
                        else
                            for iRep=1:REPS
                                ep_tictoc;if EPtictoc.stop;return;end
                                [~, ~, RESULTSMW, MSE]=runRobust(Yscaled, cNX, cBcontrast, cWcontrast', OPT1, PER, OPT2, NUMSIM, SEED*iRep, MISSING, 0, alpha, SCALE, LOC1, LOC2);
                                resultsTot{iRep}=RESULTSMW;
                                pList(iRep)=RESULTSMW(4);
                            end
                        end
                        [A B]=sort(pList);
                        RESULTSMW=resultsTot{find(B==ceil(length(pList)/2))};
                        if isempty(RESULTSMW)
                            return
                        end

                        [~, ~, ~, MSE]=ep_WJGLMml_mat(Yscaled, cNX, cBcontrast, cWcontrast', OPT1, PER, OPT2, 1, SEED, MISSING, OPT3, alpha, SCALE, LOC1, LOC2);
                        if isempty(cMUHAT)
                            msg='Error: ANOVA run aborted.';
                            [msg]=ep_errorMsg(msg);
                            return
                        end

                        alpha.pvar=std(pList)*2;
                        testResultsMW.statsType='robust';
                        testResultsMW.effectSizeTest='d<sub>R</sub>';
                        testResultsMW.GPOWERtest='';
                        testResultsMW.stat=RESULTSMW(1);
                        testResultsMW.numDF=RESULTSMW(2);
                        testResultsMW.denDF=RESULTSMW(3);
                        testResultsMW.pValue=RESULTSMW(4);
                        testResultsMW.epsilon=NaN;
                        testResultsMW.MSE=MSE;
                        testResultsMW.statsTest='N-way';
                        testResultsMW.effectSize=RESULTSMW(5);
                        testResultsMW.lowerConfid=RESULTSMW(6);
                        testResultsMW.upperConfid=RESULTSMW(7);
                        testResultsMW.GPOWER=NaN;
                        testResultsMW.meanR=[];
                    else
                        %conventional statistics
                        if statsToolbox
                            [scaleAnovaTable, scaleRM] = setupANOVA(Yscaled, factorTable, factorGroupTable, facNum, facGroupNum, varNum, contrastName, contrastGroupName, factorNames, factorGroupNames, betweenLabels);
                            testResultsMW = runANOVA(scaleAnovaTable, scaleRM, factorGroupTable, factorTable, betweenGroup, withinGroup, contrastGroupName, contrastName, contrast, epsilonType);
                        else
                            %handrolled conventional ANOVAs
                            disp('Not functional yet');
                            return
                            %[MUHAT, STDIZER, RESULTS, MSE]=ep_WJGLMml_mat(Y, NX, groupContrast{betweenGroup}, contrast{withinGroup}', OPT1, PER, OPT2, NUMSIM, SEED, MISSING, OPT3, alpha, SCALE, LOC1, LOC2);
                        end
                        alpha.pvar=0;
                    end
                    fprintf(outfid,[repmat('&nbsp;',1,followup*2) '</BR>\n<i>Vector Scaling Test (is the scalp topography effect genuine?):</BR>\n']);
                    errorFlag=ep_printADFResults(testResultsMW, alpha, followup, outfid, ANOVAoptions);
                    if errorFlag
                        msg='Error: ANOVA run aborted.';
                        [msg]=ep_errorMsg(msg);
                        return
                    end
                    fprintf(outfid,'</i>');
                end
            end

            %perform ICC reliability test.
            if ~isempty(sessFactors) && ~isempty(contrastFactors)
                if any(and(contrastFactors(withinGroup,:),sessFactors')) && ~any((contrastFactors(withinGroup,:)-sessFactors')>0)%only sess factor?
                    if  isempty(betweenContrastFactors) || all(betweenContrastFactors(betweenGroup,:))
                        if ~ICCflag
                            disp('ICC using Robert Matthew (2019). f_ICC (https://www.github.com/robertpetermatthew/f_ICC), GitHub. Retrieved December 29, 2019.');
                            ICCflag=1;
                        end
                        ICC = f_ICC(Y,.05);
                        ICCmodel=3; %recommended for test-retest: (Qin, Nelson, McLeod, Eremenco, & Coons, 2019)
                        P=sprintf('%10.8f', ICC{ICCmodel}.pVal);
                        Pp=findstr('.',P);
                        Pz=findstr(P(Pp+1:length(P)),'0');
                        for i=1:length(Pz)
                            if i ~= Pz(i)
                                break
                            end
                        end
                        if isempty(i)
                            i=1;
                        end
                        if isnan(ICC{ICCmodel}.pVal) || isempty(ICC{ICCmodel}.pVal)
                            pSign='=';
                            pVal=' could not be calculated';
                        elseif ICC{ICCmodel}.pVal >= .00000001
                            pSign='=';
                            pVal=sprintf(['%1.' num2str(i+1) 'f'], ICC{ICCmodel}.pVal);
                        else
                            pSign='<';
                            pVal='0.00000001';
                        end

                        fprintf(outfid,[repmat('&nbsp;',1,followup*2) '</BR>\n<i>Intra-class coefficient reliability ' ICC{ICCmodel}.nameMcGraw ' ' ICC{ICCmodel}.nameShrout ':</BR>\n']);
                        fprintf(outfid,[repmat('&nbsp;',1,followup*2) 'Rho=%1.2f,F(%1.1f,%1.1f)=%1.2f, p%s%s</BR>\n\n'], ICC{ICCmodel}.est, ICC{ICCmodel}.df1, ICC{ICCmodel}.df2, ICC{ICCmodel}.FValue, pSign, pVal);
                        fprintf(outfid,'</i>');
                    end
                end
            end

            %perform follow-up ANOVAs of interactions by recursively calling upon this function
            %For the follow-up ANOVAs, there are three types of ANOVA factors to consider:
            % 1) the factor where one level is being held constant and the other levels are excluded.
            % 2) the factors which are entered in the normal way (retained factors)
            % 3) the factors which are not being considered and whose levels are therefore combined together.
            % The factor structure for the ANOVA is based on the full model but only the contrast corresponding to the
            % follow-up is actually computed.

            if (testResults.pValue <= alpha.uncorrected) || allPostHoc
                betweenFactorList=find(betweenContrastFactors(betweenGroup,:));
                withinFactorList=find(contrastFactors(withinGroup,:));
                if ((sum(contrastFactors(withinGroup,:)) + sum(betweenContrastFactors(betweenGroup,:)))>1) %interaction so need follow-up ANOVAs
                    if ~followup
                        fprintf(outfid,[repmat('&nbsp;',1,followup*2) '</BR>\n' repmat('#',1,60) '</BR>\n']);
                    end
                    numContrasts=length(withinFactorList)*length(betweenFactorList);
                    totalPostHoc=1;
                    for iFactor=1:length(betweenFactorList)
                        totalPostHoc=totalPostHoc*length(levelGroupNames{iFactor});
                    end
                    for iFactor=1:length(withinFactorList)
                        totalPostHoc=totalPostHoc*length(levelNames{iFactor});
                    end
                    postHocAlpha=alpha;
                    postHocAlpha.corrected=1-(1-postHocAlpha.corrected)^(1/totalPostHoc); %Dunn-Šidák
                    fprintf(outfid,'<font size="1">');
                    fprintf(outfid,[repmat('&nbsp;',1,(followup+1)*2) 'Post-hoc alpha with Dunn-Šidák: '  num2str(postHocAlpha.corrected) '</BR>\n']);
                    fprintf(outfid,'<font size="2">');
                    for betweenFact=1:length(betweenFactorList)
                        theBetweenFactor=betweenFactorList(betweenFact); %the one being kept constant
                        if covariate(theBetweenFactor)~=2
                            retainedFactors=setdiff(betweenFactorList,theBetweenFactor); %the factors being analyzed in the follow-up
                            otherFacs=(setdiff([1:length(factorGroupNames(betweenFactorList))],theBetweenFactor)); %the set of factors (whether retained or ignored) other than the one being held constant
                            for betweenLevel=1:length(levelGroupNames{theBetweenFactor})
                                theConstantGrps=find(strcmp(levelGroupNames{theBetweenFactor}(betweenLevel),factorGroupTable(:,theBetweenFactor))); %the between cells that are entering the follow-up ANOVAs
                                constantFactorGroupTable=factorGroupTable(theConstantGrps,:); %the part of the factor table that is being held constant and thus entered into the follow-up
                                constantNX=NX(theConstantGrps); %the part of NX that is being held constant and thus entered into the follow-up
                                constantY=[];
                                constantBetween=[];
                                %for the factor being held constant, retain only the held level
                                counter=1;
                                for iGroup=1:length(NX)
                                    if any(theConstantGrps == iGroup)
                                        constantY=[constantY; Y(counter:NX(iGroup)+counter-1,:)]; %the part of Y that is being held constant and thus entered into the follow-up
                                        constantBetween=[constantBetween; ANOVAinfo.betweenLvl(counter:NX(iGroup)+counter-1,:)]; %the part of betweenLvl that is being held constant and thus entered into the follow-up
                                    end
                                    counter=counter+NX(iGroup);
                                end

                                %do the follow-up ANOVA
                                fprintf(outfid,'<font size="1">');
                                fprintf(outfid,[repmat('&nbsp;',1,(followup+1)*2) 'Holding level ' levelGroupNames{theBetweenFactor}(betweenLevel) ' of factor ' factorGroupNames{theBetweenFactor} ' constant.']);
                                posthocdata=ANOVAinfo;
                                posthocdata.covariate=posthocdata.covariate(otherFacs);
                                posthocdata.betweenLvl=constantBetween(:,otherFacs);
                                if isempty(withinFactorList)
                                    constantY=mean(constantY,2);
                                    constantFactorNames=cell(0);
                                    constantLevelNames=cell(0);
                                else
                                    constantFactorNames=factorNames;
                                    constantLevelNames=levelNames;
                                end
                                constantANOVAdata=ANOVAdata;
                                constantANOVAdata.subjects=constantNX;
                                [cellTables, plotTables, tableCounter] = ep_ADF(constantY, constantANOVAdata, OPT1, ANOVAoptions, OPT2, constantFactorNames, constantLevelNames, factorGroupNames(otherFacs), levelGroupNames(otherFacs), elecFactors, sessFactors, alpha, followup+1, OPT3, SCALE, LOC1, LOC2, outfid, factorNames(withinFactorList), factorGroupNames(retainedFactors), theHeader, allPostHoc, posthocdata, cellTables, plotTables, tableCounter, lastFlag);
                                fprintf(outfid,'<font size="2">');
                            end
                        end
                    end
                    for withinFact=1:length(withinFactorList)
                        theWithinFactor=withinFactorList(withinFact); %factor whose level is being held constant
                        retainedFactors=setdiff(withinFactorList,withinFactorList(withinFact)); %the factors being analyzed in the follow-up
                        otherFacs=setdiff([1:length(factorNames)],theWithinFactor); %the set of factors other than the one being held constant
                        for withinLevel=1:length(levelNames{theWithinFactor})
                            theConstantLvls=find(strcmp(levelNames{theWithinFactor}(withinLevel),factorTable(theWithinFactor,:))); %the within cells that are entering the follow-up ANOVAs
                            constantFactorTable=factorTable(:,theConstantLvls); %the part of the factor table that is being held constant and thus entered into the follow-up
                            constantY=[];

                            %retain the appropriate within groups and collapse over the irrelevant within group factors
                            for i=1:varNum
                                if any(theConstantLvls == i)
                                    constantY(:,end+1)=Y(:,i); %the part of Y that is being held constant and thus entered into the follow-up
                                end
                            end
                            fprintf(outfid,'<font size="1">');
                            fprintf(outfid,[repmat('&nbsp;',1,(followup+1)*2) 'Holding level ' levelNames{theWithinFactor}(withinLevel) ' of factor ' factorNames{theWithinFactor} ' constant.']);
                            [cellTables, plotTables, tableCounter] = ep_ADF(constantY, ANOVAdata, OPT1, ANOVAoptions, OPT2, factorNames(otherFacs), levelNames(otherFacs), factorGroupNames, levelGroupNames, elecFactors(otherFacs), sessFactors(otherFacs), postHocAlpha, followup+1, OPT3, SCALE, LOC1, LOC2, outfid, factorNames(retainedFactors), factorGroupNames(betweenFactorList), theHeader, allPostHoc, ANOVAinfo, cellTables, plotTables, tableCounter, lastFlag);
                            fprintf(outfid,'<font size="2">');
                        end
                    end
                elseif ~isempty(betweenFactorList) %run pairwise follow-up contrasts if it is a single between factor and it has more than two levels.
                    numBetween=length(levelGroupNames{betweenFactorList});
                    if (numBetween > 2) && (covariate(betweenFactorList)~=2)
                        theContrast=groupContrast{betweenGroup};
                        levelIndex=zeros(length(NX),1);
                        levelIndex(find(theContrast(1,:) > 0))=1;
                        for iContrast=1:size(theContrast,1)
                            levelIndex(find(theContrast(iContrast,:) < 0))=iContrast+1;
                        end
                        levelPairs = nchoosek([1:numBetween],2);
                        numContrasts=size(levelPairs,1);
                        postHocAlpha=alpha;
                        if ~OPT2 %conventional statistics
                            subList=zeros(size(Y,1),1);
                            for iGroup=1:length(levelIndex)
                                subList(1+sum(NX(1:iGroup-1)):sum(NX(1:iGroup)))=levelIndex(iGroup);
                            end
                            [p,tbl,stats] = anova1(mean(Y,2),subList,'off');
                            postHocResults = multcompare(stats,'CType',posthocType,'Display','off');
                        end
                        if ~OPT2 && statsToolbox
                            fprintf(outfid,[repmat('&nbsp;',1,(followup+1)*2) 'Pairwise between-group post-hoc alpha using ' posthocType ' starting with an alpha of: '  num2str(postHocAlpha.corrected) '</BR>\n']);
                        else
                            postHocAlpha.corrected=1-(1-postHocAlpha.corrected)^(1/numContrasts); %Dunn-Šidák if not using something else
                            fprintf(outfid,[repmat('&nbsp;',1,(followup+1)*2) 'Post-hoc alpha with Dunn-Šidák: '  num2str(postHocAlpha.corrected) '</BR>\n']);
                        end
                        for iPairs = 1:numContrasts
                            % C=zeros(1,length(cNX));
                            % C(levelPairs(iPairs,1))=1;
                            % C(levelPairs(iPairs,2))=-1;
                            C=[1, -1];
                            if OPT2
                                %robust statistics
                                resultsTot=cell(REPS,1);
                                pList=zeros(REPS,1);
                                cpY=[cY(1+sum(cNX(1:levelPairs(iPairs,1)-1)):sum(cNX(1:levelPairs(iPairs,1))),:); cY(1+sum(cNX(1:levelPairs(iPairs,2)-1)):sum(cNX(1:levelPairs(iPairs,2))),:)];
                                if ft_hastoolbox('DISTCOMP') && (EPmain.preferences.advanced.parallel==1)
                                    ep_tictoc;if EPtictoc.stop;return;end
                                    parfor iRep=1:REPS
                                        [MUHAT, STDIZER, RESULTS, MSE]=runRobust(cpY, cNX(levelPairs(iPairs,:)), C, [], OPT1, PER, OPT2, NUMSIM, SEED*iRep, MISSING, 0, postHocAlpha, SCALE, LOC1, LOC2);
                                        resultsTot{iRep}=RESULTS;
                                        pList(iRep)=RESULTS(4);
                                    end
                                    [~, ~, ~, MSE]=runRobust(cpY, cNX(levelPairs(iPairs,:)), C, [], OPT1, PER, OPT2, NUMSIM, 1, MISSING, 0, postHocAlpha, SCALE, LOC1, LOC2);
                                else
                                    for iRep=1:REPS
                                        ep_tictoc;if EPtictoc.stop;return;end
                                        [MUHAT, STDIZER, RESULTS, MSE]=runRobust(cpY, cNX(levelPairs(iPairs,:)), C, [], OPT1, PER, OPT2, NUMSIM, SEED*iRep, MISSING, 0, postHocAlpha, SCALE, LOC1, LOC2);
                                        resultsTot{iRep}=RESULTS;
                                        pList(iRep)=RESULTS(4);
                                    end
                                end
                                [~,B]=sort(pList);
                                RESULTS=resultsTot{find(B==ceil(length(pList)/2))};
                                if isempty(RESULTS)
                                    return
                                end

                                testResults=[];
                                %effect size as only the matlab code computes effect sizes and also MSE.
                                [~, ~, esRESULTS, MSE]=ep_WJGLMml_mat(cpY, cNX(levelPairs(iPairs,:)), C, [], OPT1, PER, OPT2, NUMSIM, SEED, MISSING, OPT3, alpha, SCALE, LOC1, LOC2);
                                if isempty(cMUHAT)
                                    msg='Error: ANOVA run aborted.';
                                    [msg]=ep_errorMsg(msg);
                                    return
                                end
                                testResults.MSE=MSE;
                                testResults.effectSize=esRESULTS(5);
                                testResults.effectSizeTest='d<sub>R</sub>';
                                testResults.lowerConfid=esRESULTS(6);
                                testResults.upperConfid=esRESULTS(7);

                                postHocAlpha.pvar=std(pList)*2;
                                testResults.stat=RESULTS(1);
                                testResults.numDF=RESULTS(2);
                                testResults.denDF=RESULTS(3);
                                testResults.pValue=RESULTS(4);
                                testResults.epsilon=NaN;
                                testResults.statsTest='independent samples t-test';
                                testResults.statsType='robust';
                                testResults.GPOWER=NaN;
                                testResults.GPOWERtest='';
                                testResults.meanR=[];
                            else
                                %conventional statistics
                                if statsToolbox
                                    subList=zeros(size(Y,1),1);
