                                contrastName2=[ANOVAdata.sessNames{contrast2} '-'];
                            end
                            contrastName1=[contrastName1 ANOVAdata.cellNames{contrast1}];
                            contrastName2=[contrastName2 ANOVAdata.cellNames{contrast2}];
                            if ~isempty(ANOVAdata.areaNames)
                                contrastName1=[contrastName1 '-' ANOVAdata.areaNames{contrast1}];
                                contrastName2=[contrastName2 '-' ANOVAdata.areaNames{contrast2}];
                            end

                            fprintf(outfid,[repmat('&nbsp;',1,(followup+1)*2) 'Contrasting ' contrastName1 ' versus ' contrastName2 '.']);
                            errorFlag=ep_printADFResults(testResults, postHocAlpha, followup+1, outfid, ANOVAoptions);
                            if errorFlag
                                msg='Error: ANOVA run aborted.';
                                [msg]=ep_errorMsg(msg);
                                return
                            end
                        end
                    end
                end
            end
        end
    end
end

