function testResults = runANOVA(ranovatbl, theRM, factorGroupTable, factorTable, betweenGroup, withinGroup, contrastGroupName, contrastName, contrast, epsilonType)
%run a conventional ANOVA using Matlab's Statistics Toolbox

if isempty(factorGroupTable) || (betweenGroup==1)
    theEffect='(Intercept):';
else
    theEffect='';
end
if isempty(factorTable) || (withinGroup==1)
    theError='Error';
else
    theError='Error(';
end
theStr=contrastGroupName{betweenGroup};
while ~isempty(theStr)
    [token theStr]=strtok(theStr,' * ');
    theEffect=[theEffect token ':'];
end
theStr=contrastName{withinGroup};
while ~isempty(theStr)
    [token theStr]=strtok(theStr,' * ');
    theEffect=[theEffect token ':'];
    theError=[theError token ':'];
end
theEffect=theEffect(1:end-1);
if ~strcmp(theError,'Error')
    theError(end)=')';
end

testResults=[];
if ~isempty(factorTable)
    epsilonTable=epsilon(theRM,contrast{withinGroup}');
    switch epsilonType
        case 'Greenhouse-Geisser'
            testResults.pValue=table2array(ranovatbl(theEffect,'pValueGG'));
            testResults.epsilon=table2array(epsilonTable(1,'GreenhouseGeisser'));
        case 'Huynd-Feldt'
            testResults.pValue=table2array(ranovatbl(theEffect,'pValueHF'));
            testResults.epsilon=table2array(epsilonTable(1,'HuynhFeldt'));
        case 'Lower Bound'
            testResults.pValue=table2array(ranovatbl(theEffect,'pValueLB'));
            testResults.epsilon=table2array(epsilonTable(1,'LowerBound'));
        otherwise
            error('Oops .. programmer error')
    end
else
    testResults.pValue=table2array(ranovatbl(theEffect,'pValue'));
end
testResults.stat=table2array(ranovatbl(theEffect,'F'));
testResults.numDF=table2array(ranovatbl(theEffect,'DF'));
testResults.denDF=table2array(ranovatbl(theError,'DF'));
testResults.MSE=table2array(ranovatbl(theError,'MeanSq'));
testResults.meanR=[];

%partial eta-squared according to Lakens(2013)
SSeffect=table2array(ranovatbl(theEffect,'SumSq'));
SSerror=table2array(ranovatbl(theError,'SumSq'));
partEtaSqSPSS=SSeffect/(SSeffect+SSerror);

if withinGroup>1 %if there is a within-group factor
    Y=theRM.BetweenDesign;
    theContrast=contrast{withinGroup};
    Y=table2array(Y(:,1:size(theContrast,2)));
    [levelList, ~, indexList]=unique(theContrast','rows','stable');
    newData=zeros(size(Y,1),length(levelList));
    for iLevel=1:length(levelList)
        newData(:,iLevel)=mean(Y(:,indexList==iLevel),2);
    end
    Rmatrix=corrcoef(newData);
    testResults.meanR=mean(Rmatrix(find(~tril(ones(size(Rmatrix))))));

    %conversion to SPSS partial eta-squared derived from Lakens(2013) appendix
    %     covMat=table2array(theRM.Covariance);
    %     corMat=diag(diag(sqrt(covMat.^-1)))*covMat*diag(diag(sqrt(covMat.^-1)));
    %     corMat=corrcoef(newData,'Rows','complete'); %drops any observations with missing data.
    %     rho=mean(tril(corMat,-1),'all'); %average of all the pairwise correlations
    %     sampSize=size(Y,1);
    %     numGroups=size(factorGroupTable,1);
    %     numReps=size(newData,2);
    %     partEtaSq=(partEtaSqSPSS*sampSize*numReps/(2*(1-partEtaSqSPSS)*(sampSize-numGroups)*(numReps-1)*(1-rho)));
    %     testResults.GPOWER=sqrt(partEtaSq/(1-partEtaSq));
    %     testResults.GPOWER(2)=rho;
end
testResults.GPOWER=sqrt(partEtaSqSPSS/(1-partEtaSqSPSS));
testResults.effectSize=partEtaSqSPSS;
testResults.effectSizeTest='partEtaSqSPSS';
%testResults.GPOWER=sqrt(partEtaSqSPSS/(1+partEtaSqSPSS)); %the SPSS version of the f statistic that G*POWER needs.
testResults.GPOWERtest='G*POWER SPSS f';
testResults.statsTest='N-way';
testResults.lowerConfid=NaN;
testResults.upperConfid=NaN;
testResults.statsType='conventional';

