function [ranovaTable, rm] = setupANOVA(Y, factorTable, factorGroupTable, facNum, facGroupNum, varNum, contrastName, contrastGroupName, factorNames, factorGroupNames, betweenLabels)
%set up a conventional ANOVA using Matlab's Statistics Toolbox

if isempty(contrastGroupName) || (isempty(contrastGroupName{1}) && length(contrastGroupName)==1)
    contrastGroupName=factorGroupNames; %for one between group factor, contrast name will be empty so need to provide it.
end
if isempty(contrastName) || (isempty(contrastName{1}) && length(contrastName)==1)
    contrastName=factorNames; %for one within group factor, contrast name will be empty so need to provide it.
end

%Y(Y==MISSING)=NaN;
dataTable=array2table(Y);
if isempty(factorTable)
    withinMeas=[];
else
    withinMeas = cell2table(factorTable');
    for iFactor=1:facNum
        eval(['withinMeas.Properties.VariableNames{''Var' num2str(iFactor) '''}=factorNames{iFactor};'])
    end
end
if isempty(factorGroupTable)
    %within only
    rm = fitrm(dataTable,['Y1-Y' num2str(varNum) ' ~ 1'],'WithinDesign',withinMeas);
    ranovaTable = ranova(rm,'WithinModel',contrastName{end});
else
    %betweenMeas = cell2table(betweenLabels);
    for iFactor=1:facGroupNum
        if ~all(cellfun(@isempty,factorGroupTable(:,iFactor))) %not categorical if it is a covariate
            dataTable=[dataTable cell2table(betweenLabels(:,iFactor))];
            eval(['dataTable.Var1=categorical(dataTable.Var1);']);
        else
            dataTable=[dataTable array2table(cellfun(@str2double,betweenLabels(:,iFactor)))];
        end
        eval(['dataTable.Properties.VariableNames{''Var1''}=factorGroupNames{iFactor};']);
    end
    if isempty(factorTable)
        %between only
        if size(Y,2)==1
            rm = fitlm(dataTable,['Y ~ ' contrastGroupName{end}]);
            ranovaTable = anova(rm);
        else
            rm = fitrm(dataTable,['Y1-Y' num2str(varNum) ' ~ ' contrastGroupName{end}]);
            ranovaTable = ranova(rm);
        end

    else
        %between and within
        rm = fitrm(dataTable,['Y1-Y' num2str(varNum) ' ~ ' contrastGroupName{end}],'WithinDesign',withinMeas);
        ranovaTable = ranova(rm,'WithinModel',contrastName{end});
    end
end

