function [MUHAT, STDIZER, RESULTS, MSE]=runRobust(Y, NX, groupContrast, contrast, OPT1, PER, OPT2, NUMSIM, SEED, MISSING, OPT3, alpha, SCALE, LOC1, LOC2)
Y(isnan(Y))=MISSING; %the robust code recognizes missing data code number but not NaN.

try
    [MUHAT, STDIZER, RESULTS, MSE]=ep_WJGLMml(Y, NX, groupContrast, contrast, OPT1, PER, OPT2, NUMSIM, SEED, MISSING, 0, alpha, SCALE, LOC1, LOC2);
catch ME
    disp(ME.message);
    disp('Mex function failed - using slower Matlab code.');
    [MUHAT, STDIZER, RESULTS, MSE]=ep_WJGLMml_mat(Y, NX, groupContrast, contrast, OPT1, PER, OPT2, NUMSIM, SEED, MISSING, 0, alpha, SCALE, LOC1, LOC2);
end
RESULTS(9)=NaN;
RESULTS(10)=NaN;

