function [NXnm, NXt, Ynm, Yt]=sampleSize(Y, NX, OPT1, PER, MISSING)
Y(isnan(Y))=MISSING; %the robust code recognizes missing data code number but not NaN.

if ~isempty(MISSING) %calculate sample sizes after missing values dropped but without trimming.
    NXnm= zeros(1,length(NX));
    count=0;
    for iGroup = 1:length(NX)
        for obs = 1:NX(iGroup)
            count=count+1;
            if isempty(find(Y(count,:)==MISSING, 1))
                NXnm(iGroup)=NXnm(iGroup)+1;
            end
        end
    end
    Ynm=Y(~any(Y==MISSING,2),:);
else
    NXnm=NX;
end

if OPT1
    NXt= zeros(1,length(NX));
    Yt=[];
    nmCount=0;
    tCount=0;
    for iGroup = 1:length(NX)
        trimNum=(floor(PER.*NXnm(iGroup)));
        NXt(iGroup)=NXnm(iGroup)-2*trimNum;
        for iWithin=1:size(Ynm,2)
            cellY=sort(Ynm(1+nmCount:NXnm(iGroup)+nmCount,iWithin));
            Yt(1+tCount:tCount+NXt(iGroup),iWithin)=cellY(1+trimNum:end-trimNum);
        end
        nmCount=nmCount+NXnm(iGroup);
        tCount=tCount+NXt(iGroup);
    end
else
    NXt=NXnm;
    Yt=Y;
end